#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────
#
# 稿得快 GEO 客户端：发布签名凭据向导
# 对应 docs/superpowers/specs/2026-11-10-release-signing-distribution-design.md §4 / §7。
# 只做「人必须在浏览器/钥匙串里点」的部分；能自动算的（base64、随机密码、写 secret）都由脚本做。
#
# ⚠ ENV_FILE 必须指向仓库外。mise 任务 `signing:wizard` 已经把它设成
#   ~/.config/gdk-geo/signing.env —— 证书与私钥永不落仓库（DR-R9）。

TOTAL_STAGES=8

# 守卫：ENV_FILE 若落在仓库内就直接拒绝，避免把 .p12 base64 写进工作区
if [[ "$ENV_FILE" == "$PWD"* || "$ENV_FILE" != /* ]]; then
  printf '\n  %s✗ 拒绝运行%s：ENV_FILE=%s 不是仓库外的绝对路径。\n' "$RED" "$RESET" "$ENV_FILE"
  printf '  请用：mise run signing:wizard\n'
  printf '  或：  ENV_FILE="$HOME/.config/gdk-geo/signing.env" scripts/setup-signing.sh\n\n'
  exit 1
fi
mkdir -p "$(dirname "$ENV_FILE")"
touch "$ENV_FILE" && chmod 600 "$ENV_FILE"

# 库里的 write_env 按 `KEY=VALUE` 原样写。值里带空格（APPLE_SIGNING_IDENTITY 必然是
# "Developer ID Application: 公司名 (TEAMID)"）会让 `source signing.env` 直接报
# "unknown file attribute"。2026-11-11 实测踩过。这里补一个单引号转义版，
# 只在本向导的 stage 里用，不动上面的库（库的跨向导一致性仍然保持）。
write_env_q() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/\'\\\'\'}" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  chmod 600 "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

banner "稿得快 GEO：发布签名凭据配置"

# ── Stage 1 ──────────────────────────────────────────────────────────────
stage "确认 Apple 账号等级与角色"
say "两件事不满足，后面全部白做："
step "1) 必须是**付费** Apple Developer Program（99 美元/年）。免费账号**无法公证**，应用仍显示「未验证」。"
step "2) 你必须是账号的 **Account Holder**。Tauri 官方文档明确：只有 Account Holder 能创建 Developer ID Application 证书。"
open_url "https://developer.apple.com/account"
step "看 Membership 一栏：Program = Apple Developer Program、Status = Active、Expiration 有未来日期。"
step "再看 People 一栏里你自己的角色是否为 Account Holder。"
warn "如果你注册的是「iOS 开发者账号」的免费版，或你不是 Account Holder，现在停下先去解决。"
pause "确认已满足两条（Enter 继续 / Ctrl-C 中止）："

# ── Stage 2 ──────────────────────────────────────────────────────────────
stage "创建 Developer ID Application 证书"
say "用 macOS 自带的「钥匙串访问」生成 CSR，私钥留在钥匙串里，这是官方推荐路径。"
step "打开「钥匙串访问」→ 菜单栏 证书助理 → **从证书颁发机构请求证书…**"
step "填你的邮箱与常用名，选「存储到磁盘」，存成 CertificateSigningRequest.certSigningRequest"
note "提示：Tauri 文档提到 CSR 可以用另一个用户邮箱生成，从而把证书绑到别的 Apple ID 上。"
open_url "https://developer.apple.com/account/resources/certificates/add"
step "证书类型选 **Developer ID Application**（不是 Apple Distribution——那是上架 App Store 用的）。"
step "上传刚才的 CSR → Continue → Download，得到 .cer 文件。"
step "双击 .cer 装进 login 钥匙串。"
warn "若装完在「钥匙串访问 → 我的证书」里看不到它：确认「默认钥匙串」里 login 是被选中的。"
step "回到终端验证（证书只有关联到你的 Apple ID 才有效，无效证书不会出现在这个输出里）："
note "  security find-identity -v -p codesigning"
say ""
say "把输出里 **Developer ID Application** 那一行引号内的完整名称复制下来，形如："
note '  Developer ID Application: Your Name (ABCDE12345)'
ask APPLE_SIGNING_IDENTITY "粘贴 Developer ID Application 身份全名："
if [[ "$APPLE_SIGNING_IDENTITY" != *"Developer ID Application"* ]]; then
  warn "这个身份不含 'Developer ID Application'，用它签名的包**过不了 Gatekeeper**。"
  confirm "仍要保留这个值？" || ask APPLE_SIGNING_IDENTITY "重新粘贴："
fi
write_env_q APPLE_SIGNING_IDENTITY "$APPLE_SIGNING_IDENTITY"
# Team ID 就是身份末尾括号里那串
TEAM_FROM_ID="$(printf '%s' "$APPLE_SIGNING_IDENTITY" | sed -n 's/.*(\([A-Z0-9]\{10\}\))$/\1/p')"
if [[ -n "$TEAM_FROM_ID" ]]; then
  write_env APPLE_TEAM_ID "$TEAM_FROM_ID"
  note "已从身份串里解析出 Team ID：$TEAM_FROM_ID"
else
  ask APPLE_TEAM_ID "手工填 Team ID（账号 Membership 页可查）："
  write_env APPLE_TEAM_ID "$APPLE_TEAM_ID"
fi

# ── Stage 3 ──────────────────────────────────────────────────────────────
stage "导出 .p12 并转 base64（APPLE_CERTIFICATE）"
say "CI 里没有图形界面，证书必须以 base64 的 .p12 形式传进去。"
step "钥匙串访问 → login 钥匙串 → **我的证书** 标签 → 展开 Developer ID Application 条目"
step "右键点它下面的**私钥**（不是证书本身）→ 导出 → 格式选 .p12 → 设一个密码"
ask P12_PATH "导出的 .p12 文件路径（可直接拖进终端）："
P12_PATH="${P12_PATH%\"}"; P12_PATH="${P12_PATH#\"}"
if [[ ! -f "$P12_PATH" ]]; then
  warn "找不到文件：$P12_PATH"
  ask P12_PATH "重新填 .p12 路径："
fi
if [[ -f "$P12_PATH" ]]; then
  ask_secret APPLE_CERTIFICATE_PASSWORD ".p12 的导出密码："
  if command -v openssl >/dev/null 2>&1; then
    APPLE_CERTIFICATE="$(openssl base64 -A -in "$P12_PATH")"
    if [[ -n "$APPLE_CERTIFICATE" ]]; then
      write_env APPLE_CERTIFICATE "$APPLE_CERTIFICATE"
      note "已自动完成 base64（$(printf '%s' "$APPLE_CERTIFICATE" | wc -c | tr -d ' ') 字符），无需你手工转换"
    else
      warn "openssl base64 输出为空，请手工执行：openssl base64 -A -in $P12_PATH"
    fi
  else
    warn "本机没有 openssl，请手工执行：openssl base64 -A -in $P12_PATH"
  fi
else
  warn "跳过 base64，稍后手工补 APPLE_CERTIFICATE"
fi
step "导出完成后把 .p12 从下载目录移走或删除，别留在仓库里。"

# ── Stage 4 ──────────────────────────────────────────────────────────────
stage "App Store Connect API Key（公证凭据）"
say "我们走 API Key 路线而不是 Apple ID + 专用密码：可细粒度授权、可单独吊销、不受改密码与双重认证影响（DR-R4）。"
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "**Integrations** 标签 → 点 Add → 名字随意（如 gdk-geo-notarize）→ 访问权限选 **Developer**"
step "Issuer ID 显示在密钥表格**上方**，复制它。"
ask APPLE_API_ISSUER "粘贴 Issuer ID："
step "表格里 **Key ID** 列的值复制下来。"
ask APPLE_API_KEY "粘贴 Key ID："
warn ".p8 私钥**只能下载一次**，而且下载按钮只在**页面刷新之后**才出现在新建那一行。现在就去刷新页面下载。"
pause "已下载 AuthKey_XXXXXX.p8 了吗？"
ask P8_PATH ".p8 文件路径（可直接拖进终端）："
P8_PATH="${P8_PATH%\"}"; P8_PATH="${P8_PATH#\"}"
if [[ -f "$P8_PATH" ]]; then
  APPLE_API_KEY_CONTENT="$(cat "$P8_PATH")"
  write_env APPLE_API_KEY_CONTENT "$APPLE_API_KEY_CONTENT"
  write_env APPLE_API_KEY "$APPLE_API_KEY"
  write_env APPLE_API_ISSUER "$APPLE_API_ISSUER"
  note "已读取 .p8 内容（CI 里会落成临时文件再导出 APPLE_API_KEY_PATH，因为 Tauri 要的是路径）"
  step "建议把 .p8 移到仓库外保存，例如 ~/.config/gdk-geo/"
else
  warn "找不到 $P8_PATH。手工执行：APPLE_API_KEY_CONTENT=\"\$(cat /path/AuthKey_XXXX.p8)\""
  write_env APPLE_API_KEY "$APPLE_API_KEY"
  write_env APPLE_API_ISSUER "$APPLE_API_ISSUER"
fi

# ── Stage 5 ──────────────────────────────────────────────────────────────
stage "生成 CI 临时钥匙串密码（KEYCHAIN_PASSWORD）"
say "这个密码只在 GitHub Actions 里建临时钥匙串时用，跟 Apple 无关，随机生成即可。"
if command -v openssl >/dev/null 2>&1; then
  KEYCHAIN_PASSWORD="$(openssl rand -hex 16)"
else
  KEYCHAIN_PASSWORD="$(date +%s%N)$RANDOM$RANDOM"
fi
write_env KEYCHAIN_PASSWORD "$KEYCHAIN_PASSWORD"
note "已生成并保存，你不需要记住它"

# ── Stage 6 ──────────────────────────────────────────────────────────────
stage "Azure Artifact Signing（Windows 签名）"
say "原名 Azure Trusted Signing，2026 年已改名。选它的理由见 DR-R3："
note "2024 年起 EV 证书不再有 SmartScreen 即时信誉，EV 的价格优势消失；"
note "Azure Artifact Signing 月费约 9.99 美元，且 Tauri 官方支持 signCommand 集成。"
warn "组织身份验证有审批周期（可能几天）。**现在就提交申请**，别等到要发版时。"
open_url "https://portal.azure.com/"
step "创建 Artifact Signing 账户（记下**账户名**与**端点 URL**，形如 https://wus2.codesigning.azure.net）"
step "在账户里创建证书配置文件 Certificate profile（记下**配置文件名**）"
step "创建 App Registration → 记下 **Directory (tenant) ID** 与 **Application (client) ID**"
step "在 App Registration 里新建一个 client secret（值只显示一次，立刻复制）"
step "给这个 App Registration 授予对该 Artifact Signing 账户的签名权限"
say ""
if confirm "现在就配 Windows 签名？（选 n 可跳过，之后重跑本向导补上）"; then
  ask_secret AZURE_TENANT_ID "Directory (tenant) ID："
  ask_secret AZURE_CLIENT_ID "Application (client) ID："
  ask_secret AZURE_CLIENT_SECRET "Client secret 的值："
  ask AZURE_CODESIGN_ENDPOINT "Artifact Signing 端点 URL（https://…codesigning.azure.net）："
  ask AZURE_CODESIGN_ACCOUNT "Artifact Signing 账户名："
  ask AZURE_CODESIGN_PROFILE "证书配置文件名："
  for kv in AZURE_TENANT_ID AZURE_CLIENT_ID AZURE_CLIENT_SECRET \
            AZURE_CODESIGN_ENDPOINT AZURE_CODESIGN_ACCOUNT AZURE_CODESIGN_PROFILE; do
    write_env "$kv" "${!kv}"
  done
else
  warn "已跳过 Windows 签名。Windows 产物将无法签名，Smart App Control 开启的机器会完全拒绝运行。"
  SKIPPED+=("Windows 签名凭据（重跑 mise run signing:wizard 补上）")
fi

# ── Stage 7 ──────────────────────────────────────────────────────────────
stage "写入 GitHub Secrets / Variables"
say "release.yml 引用的每一项都必须在仓库设置里存在，否则 job 会在第一步就 fail。"
say "清单的唯一权威表是发布规格 §7。下面按该表写入。"
if ! command -v gh >/dev/null 2>&1; then
  warn "没装 GitHub CLI（gh）。请手工到仓库 Settings → Secrets and variables → Actions 里逐个添加。"
  SKIPPED+=("全部 GitHub Secrets/Variables（未装 gh，需手工添加）")
else
  step "确认 gh 已登录且有该仓库权限：gh auth status"
  if confirm "现在写入 GitHub？（会覆盖同名 secret）"; then
    # 密文 → Secrets
    for s in APPLE_CERTIFICATE APPLE_CERTIFICATE_PASSWORD APPLE_SIGNING_IDENTITY \
             APPLE_API_ISSUER APPLE_API_KEY APPLE_API_KEY_CONTENT KEYCHAIN_PASSWORD \
             AZURE_TENANT_ID AZURE_CLIENT_ID AZURE_CLIENT_SECRET; do
      v="${!s:-}"
      if [[ -n "$v" ]]; then set_secret "$s" "$v"; else warn "$s 为空，跳过（重跑向导补上）"; fi
    done
    # 非密 → Variables
    for v in AZURE_CODESIGN_ENDPOINT AZURE_CODESIGN_ACCOUNT AZURE_CODESIGN_PROFILE APPLE_TEAM_ID; do
      val="${!v:-}"
      if [[ -n "$val" ]]; then set_var "$v" "$val"; else warn "$v 为空，跳过"; fi
    done
  else
    SKIPPED+=("GitHub Secrets/Variables（你选择了不写入）")
  fi
fi

# ── Stage 8 ──────────────────────────────────────────────────────────────
stage "本地试签与核验"
say "凭据齐了之后，先在本机跑通一次签名 + 公证，再动 CI。这是最快发现证书类型选错的方式。"
say ""
step "1) 载入本地凭据："
note "   set -a; source \"$ENV_FILE\"; set +a"
step "2) 导出 Tauri 认的公证变量名："
note '   export APPLE_API_KEY_PATH="$HOME/.config/gdk-geo/AuthKey_<KEYID>.p8"   # 要的是路径，不是内容'
step "3) 构建（首次会编译整个 workspace，比较久）："
note "   cd apps/desktop && pnpm exec tauri build --bundles dmg"
note "   # 只想先验公证、跳过装订票据：加 --skip-stapling（正式发布不可跳过）"
step "4) 核验签名 / 公证 / staple 票据 / SHA-256："
note "   mise run release:verify"
step "5) 全绿后跑发布门禁并打 tag："
note "   mise run release:check -- --history"
note "   mise run version:set -- 0.1.0   # 如需递增"
